const dialog=document.createElement('dialog');dialog.className='mir-help-dialog';dialog.setAttribute('aria-label',"Centre d’aide MIR");const launch=document.createElement('button');launch.type='button';launch.className='mir-help-launch';launch.textContent='Aide et soutien';document.body.append(launch,dialog);
