async function load(){busy=true;error='';notice='';render();try{const remote=await api()?.helpFAQ?.();faq=Array.isArray(remote)&&remote.length?remote:fallbackFAQ;if(!Array.isArray(remote)||!remote.length)notice='Les réponses essentielles sont disponibles. Le contenu détaillé sera chargé dès que le service répondra.';snapshot=connected()?await api().supportSnapshot():null;}catch(e){faq=fallbackFAQ;notice='Le service est momentanément indisponible. Les réponses essentielles restent accessibles.';}finally{busy=false;render();}}
